import { relative, resolve, sep } from 'node:path';
export function buildClientAccess(input) {
    const outputs = new Map();
    const clientPath = (path) => relative(input.outDir, resolve(input.srcDir, path)).split(sep).join('/');
    for (const graph of input.graphs) {
        for (const [path, output] of Object.entries(graph.outputs)) {
            const key = clientPath(path);
            const imports = outputs.get(key) ?? new Set();
            for (const dependency of output.imports) {
                if (!dependency.external)
                    imports.add(clientPath(dependency.path.replace(/[?#].*$/, '')));
            }
            outputs.set(key, imports);
        }
    }
    const known = new Set(input.files);
    const roots = new Set([
        ...input.islands.flatMap((island) => [island.entry, ...island.css]),
        ...input.globalCss,
    ]);
    const diagnostics = [...roots]
        .filter((root) => !known.has(root))
        .map((root) => ({
        level: 'error',
        code: 'client-access-missing-root',
        message: `The manifest references ${root}, but the build did not write it.`,
    }));
    const entries = new Map(input.islands.map((island) => [island.entry, island.id]));
    const owners = new Map();
    const closure = (root, islandId) => {
        const seen = new Set();
        const stack = [root];
        for (let path = stack.pop(); path !== undefined; path = stack.pop()) {
            if (seen.has(path) || !outputs.has(path))
                continue;
            const entryOwner = entries.get(path);
            if (entryOwner !== undefined && entryOwner !== islandId)
                continue;
            seen.add(path);
            for (const dependency of outputs.get(path) ?? [])
                stack.push(dependency);
        }
        return seen;
    };
    for (const island of input.islands) {
        for (const root of [island.entry, ...island.css]) {
            for (const path of closure(root, island.id)) {
                const ids = owners.get(path) ?? new Set();
                ids.add(island.id);
                owners.set(path, ids);
            }
        }
    }
    const files = Object.fromEntries([...input.files].sort().map((path) => [path, [...(owners.get(path) ?? [])].sort()]));
    const global = new Set(input.globalCss.flatMap((root) => [...closure(root)]));
    const globalFiles = Object.keys(files).filter((path) => global.has(path));
    return { access: { version: 1, files, globalFiles }, diagnostics };
}
